pub fn tools_screen_get_next_mode_message(game: &mut crate::game::Game<'_>, changed_mode: i32, data: i32) -> horizon_client::text::Text {
    if changed_mode == 0 {
        if data == 2 {
            return horizon_client::text::Text::literal(j_lang("Spill Mode", &[]));
        } else {
            return if data == 3 { horizon_client::text::Text::literal(j_lang("Drink Mode", &[])) } else { horizon_client::text::Text::literal(j_lang("Suck Mode", &[])) };
        }
    } else {
        return if data == 1 { horizon_client::text::Text::literal(j_lang("Selected Left Tank", &[])) } else { horizon_client::text::Text::literal(j_lang("Selected Right Tank", &[])) };
    }
    #[allow(unreachable_code)]
    unreachable!()
}

