#[allow(unused_mut, unused_variables, unused_parens, unreachable_code, clippy::all)]
pub fn sort_selector_calculate_count(game: &mut crate::game::Game<'_>, stacks: &[Option<horizon_client::items::ItemStack>]) -> JMap<String, i32> {
    let mut item_counts: JMap<String, i32> = JMap::new();
    for stack in stacks.iter() {
        if !stack.is_none() {
            let item: String = stack.as_ref().map_or_else(|| "minecraft:air".to_string(), |s| s.item.to_string());
            let count: i32 = stack.as_ref().map_or(0, |s| s.count as i32);
            item_counts.insert(item.clone(), (item_counts.get(&item.clone()).cloned().unwrap_or_else(|| 0)) + count);
        }
    }
    return item_counts.clone();
}

